add(nr=5, id="10468773232906", orig_titel="Women's Gravel Bike LIV Devote 1 (2026) Dune Beige",
 fakta="Women's Gravel Bike LIV Devote 1 (2026) Dune Beige. The Liv Devote women's gravel bike is designed to satisfy your thirst for gravel adventure. Versatile gravel bike ready for everything from short forest rides to long, winding trails. The durable and lightweight aluminium frame with a carbon fork offers a smooth and comfortable ride. The redesigned frame geometry puts you in a performance-oriented position. The bike is equipped with a flip-chip, which allows you to adjust the wheelbase. Choose a shorter wheelbase for better handling and acceleration, which is ideal for long rides. Or choose a longer wheelbase to fit wider tyres and achieve better grip, for example in the forest. The manufacturer is Giant. The Liv range is designed for women. Frame: ALUXX-grade aluminium, 12x142mm thru-axle, flat mount disc, flip chip dropout. Frame size: XS (39 cm) approx. 150–163 cm, S (42 cm) approx. 158–169 cm, M (46.5 cm) approx. 164–175 cm, L (50 cm) approx. 170–181 cm. Fork: Advanced-grade composite, full-composite OverDrive steerer, 12mm thru-axle, flat mount disc. Derailleurs: Shimano Cues. Number of gears: 20. Brakes: Shimano Cues hydraulic. Tyres: Giant CrossCut Grip 1, 700x45C. The bike has mounting points for mudguards and other accessories. Denna produkt är en beställningsvara och kan ta upp till 1 vecka längre att leverera.",
 titel='Gravelcykel Liv Devote 1 (2026) för dam, Dune Beige',
 seo_title='Gravelcykel Liv Devote 1 (2026) för dam',
 meta='Liv Devote 1 är en gravelcykel för dam med aluminiumram, justerbar hjulbas (flip-chip), 20 växlar och hydrauliska bromsar. Beställningsvara.',
 intro='Liv Devote 1 (2026) är en gravelcykel för dam med aluminiumram, justerbar hjulbas (flip-chip), 20 växlar och hydrauliska bromsar. Beställningsvara: leveranstiden kan vara upp till en vecka längre.',
 passar=['Gravelcykling på skogsvägar och längre grusstråk','Dig som vill kunna välja kort hjulbas för styrning och acceleration eller lång hjulbas för bredare däck och mer grepp','Cyklister ungefär 150–181 cm långa (ramstorlek XS–L)'],
 spec=['Ramstorlek: XS (39 cm) för ca 150–163 cm, S (42 cm) för ca 158–169 cm, M (46,5 cm) för ca 164–175 cm, L (50 cm) för ca 170–181 cm','Gaffel: Advanced-grade composite, OverDrive-styrrör, 12 mm genomgående axel, flat mount-skivbroms','Ram: ALUXX-aluminium, 12x142 mm genomgående axel, flat mount-skivbroms, flip chip-dropout','Fästpunkter för stänkskärmar och andra tillbehör','Växlar: Shimano Cues, 20 växlar','Bromsar: Shimano Cues, hydrauliska','Däck: Giant CrossCut Grip 1, 700x45C'],
 faq=[('Vad gör flip-chip?','Med flip-chip går det att justera hjulbasen. Kort hjulbas ger enligt Liv bättre styrning och acceleration. Lång hjulbas ger plats för bredare däck och mer grepp.')], marke='Liv är en cykelserie för kvinnor från Giant.',
 motivering='Engelsk källa översatt. Raden om första gravelloppet och "thirst for adventure" utelämnas som reklam.',
 att_bekrafta=['Källan säger både "carbon fork" i texten och "Advanced-grade composite" i specifikationen. Texten använder specifikationens uttryck.','Liv som Giants serie för kvinnor står i källan ("manufacturer is Giant", "range designed for women").'])

