add(nr=7, id="10472332034314", orig_titel='Stuntscooter Union Lite S Scooter Blue',
 fakta='Stuntscooter Union Lite S Scooter Blue. UNION LITE-triken är ett utmärkt val för nybörjaren som vill börja med freestyle-scooting utan en stor investering. Den här modellen erbjuder känslan och tillförlitligheten hos en riktig trike, samtidigt som den är prisvärd och lätt att hantera. Den lätta men hållbara aluminiumkonstruktionen säkerställer god kontroll och hållbarhet både i skateparken och på gatan. Tack vare IHC-kompressionssystemet och högkvalitativa ABEC-9-lager är åkturen mjuk och stabil. Total höjd: 690 mm. Vikt: 3,2930 kg (3,293 kg). Användarhöjd: 105-125 cm. Styre: 470 x 450 mm, aluminium. Hjul: 100 mm, 88A. Lager: ABEC-9. Kompression: IHC. Max. lastkapacitet: 100 kg. Märke Union',
 titel='Stuntscooter Union Lite S, blå',
 seo_title='Stuntscooter Union Lite S, blå',
 meta='Union Lite S är en stuntscooter för freestyle-åkning med aluminiumkonstruktion, IHC-kompression och ABEC-9-lager. Användarhöjd 105–125 cm, max 100 kg.',
 intro='Union Lite S är en stuntscooter för freestyle-åkning i skatepark och på gatan, med aluminiumkonstruktion, IHC-kompression och ABEC-9-lager.',
 passar=['Nybörjare som vill börja med freestyle-scooting','Åkning i skatepark och på gatan','Användare 105–125 cm långa'],
 spec=['Styre: 470 x 450 mm, aluminium','Max lastkapacitet: 100 kg','Användarhöjd: 105–125 cm','Vikt: 3,293 kg','Total höjd: 690 mm','Hjul: 100 mm, 88A','Lager: ABEC-9','Kompression: IHC'],
 faq=[], marke=None,
 motivering='Fakta ur källan. "Utmärkt val", "prisvärd" och "mjuk och stabil åktur" utelämnas som värderande. "Trike" i källan förstås som scootern och nämns inte.',
 att_bekrafta=['Källan kallar produkten "trike" men titeln säger scooter. Texten använder scooter.','Vikten i källan är "3,2930 kg", texten skriver 3,293 kg.'])

